class Solution {
public:
    bool isIdealPermutation(vector<int>& nums) {
        int n = (int)nums.size();
        for (int i = 0; i < n; ++i) {
            int v = nums[i];
            if (v - i > 1 || i - v > 1) return false;
        }
        return true;
    }
};
